import{z as o,x as n,o as A,c as d,q as l,j as r,D as a,d as B,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"提示词的多样性与覆盖","description":"","frontmatter":{"title":"提示词的多样性与覆盖","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ade-prompt-diversity.md","filePath":"llm/ade-prompt-diversity.md","lastUpdated":1791413859000}'),C={name:"llm/ade-prompt-diversity.md"};function p(m,E,D,h,u,f){const t=n("Mermaid");return A(),d("div",null,[E[2]||(E[2]=l('<h1 id="提示词的多样性与覆盖" tabindex="-1">提示词的多样性与覆盖 <a class="header-anchor" href="#提示词的多样性与覆盖" aria-label="Permalink to &quot;提示词的多样性与覆盖&quot;">​</a></h1><div class="epigraph"><p>提示分布是「好」这个字的管辖范围：哪里没有提示，哪里就没有偏好，也就没有边界。</p><footer>—— 据 Ouyang 等 InstructGPT 2022 与 Zhou 等 LIMA 2023 的提示来源口径整理</footer></div><p><a href="/llm/ade-preference-lifecycle">上一课</a>把偏好数据钉成有版本、有退役的资产，采集是循环的第一段；本课停在采集段最上游的原料上：提示词本身。要决定的不是「采多少条」，而是「提示分布覆盖什么、漏掉什么」。<a href="/llm/rm-data-sources">偏好数据的来源谱系</a>给过提示的两种填法——真实日志、标注员自写；模型生成是合成路线补上的第三条；本课写这三个分布怎么拼成一张覆盖图。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>提示分布决定偏好在哪些问题上被定义。覆盖的失效是静默的：头部意图（写邮件、改代码）被日志自然过采，长尾（冷门专业域、少数语言、非常规格式）几乎缺席；RM 在缺席处没有对比样本，分数是外推（<a href="/llm/rm-ood-behavior">分布外的奖励行为</a>的机制位），而 RL 与 best-of-n 恰好会把手伸进这些区域。三条来源各有偏置：真实日志保覆盖但脏且带隐私；自写提示干净但窄，标注员的职业画像会变成提示的画像；模型生成扩张最便宜，但生成器的分布同质化，几百条变体可能是同一个格子的重复敲门。没有一张意图分类法把三者对齐，覆盖就只是条数的错觉。</p><p><span class="marginnote">「外推」就是让模型在自己没见过例子的区域里「猜」边界在哪。类比：只见过猫和狗的标注员，第一次看到狐狸只能瞎猜它是猫还是狗——RM 在缺席格子给的分数，就是这种没有根据的猜。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先钉分类法，再谈配额。意图分类法的粒度以「行为边界是否不同」为准：同一意图下好坏答案的分界相似，就并成一类；分界不同，就拆开。分类法立起来后按三个动作填分布。真实日志先过<a href="/llm/data-quality-filter">质量过滤</a>：隐私剥离、毒性分流、模板归并，再按意图映射进池。自写提示按分类法下配额——标注员领任务，不是自由发挥。合成扩张拿聚类中心做种子，扩网格不扩头部，多样性的量法沿用<a href="/llm/synthetic-diversity-metrics">多样性的度量与覆盖</a>的口径。覆盖矩阵用「意图 × 难度 × 长度 × 语言」四维记账，每个格子设下限；持有集故意从欠覆盖的格子里切，让验证读数对薄弱处诚实。</p>',8)),(A(),r(s,null,{default:a(()=>[i(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TAX%5B%22%E6%84%8F%E5%9B%BE%E5%88%86%E7%B1%BB%E6%B3%95%EF%BC%9A%E6%8C%89%E8%A1%8C%E4%B8%BA%E8%BE%B9%E7%95%8C%E5%88%87%22%5D%20--%3E%20LOG%5B%22%E7%9C%9F%E5%AE%9E%E6%97%A5%E5%BF%97%EF%BC%9A%E6%B8%85%E6%B4%97%E5%90%8E%E6%98%A0%E5%B0%84%22%5D%0A%20%20TAX%20--%3E%20SELF%5B%22%E8%87%AA%E5%86%99%EF%BC%9A%E6%8C%89%E6%A0%BC%E9%85%8D%E9%A2%9D%22%5D%0A%20%20TAX%20--%3E%20SYN%5B%22%E5%90%88%E6%88%90%EF%BC%9A%E7%A7%8D%E5%AD%90%E6%89%A9%E7%BD%91%E6%A0%BC%22%5D%0A%20%20LOG%20--%3E%20POOL%5B%22%E6%8F%90%E7%A4%BA%E6%B1%A0%22%5D%0A%20%20SELF%20--%3E%20POOL%0A%20%20SYN%20--%3E%20POOL%0A%20%20POOL%20--%3E%20COV%5B%22%E8%A6%86%E7%9B%96%E7%9F%A9%E9%98%B5%EF%BC%9A%E6%84%8F%E5%9B%BE%C3%97%E9%9A%BE%E5%BA%A6%C3%97%E9%95%BF%E5%BA%A6%C3%97%E8%AF%AD%E8%A8%80%22%5D%0A%20%20COV%20--%3E%7C%22%E6%AC%A0%E8%A6%86%E7%9B%96%E6%A0%BC%E5%88%87%E6%8C%81%E6%9C%89%E9%9B%86%22%7C%20HOLD%5B%22%E6%8C%81%E6%9C%89%E9%9B%86%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"为什么配额要对长尾过采：若按使用频率配，头部意图占九成样本，而每条样本的边际信息量随同簇密度递减——第一千封「帮我写邮件」教会 RM 的东西趋近于零，长尾格子里第一条样本定义的却是整块边界。所以配额的真实语义是「按每格的信息价值分配」，不是按自然频率。三条来源的机制分工由此清晰：日志提供真实分布的形状（什么问题真的会出现），自写提供格子的最低保障，合成提供密度与格式变体；三者拼起来，分类法才是那张对齐表——同一个格子里的三条来源，测的才是同一件事。",-1)),E[5]||(E[5]=e("p",null,"同样一条数据，落在头部还是长尾，价值差出几个量级——这是配额不按频率分的机制图：",-1)),(A(),r(s,null,{default:a(()=>[i(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20H%5B%22%E5%A4%B4%E9%83%A8%E6%84%8F%E5%9B%BE%EF%BC%9A%E5%B8%AE%E6%88%91%E5%86%99%E9%82%AE%E4%BB%B6%22%5D%20--%3E%7C%22%E7%AC%AC%201%20%E6%9D%A1%22%7C%20V1%5B%22%E5%AE%9A%E4%B9%89%E5%A5%BD%E5%9D%8F%E5%88%86%E7%95%8C%EF%BC%9A%E4%BB%B7%E5%80%BC%E5%A4%A7%22%5D%0A%20%20H%20--%3E%7C%22%E7%AC%AC%201000%20%E6%9D%A1%22%7C%20V2%5B%22%E5%90%8C%E7%B0%87%E9%87%8D%E5%A4%8D%E6%95%B2%E9%97%A8%EF%BC%9A%E4%BB%B7%E5%80%BC%E7%BA%A6%E7%AD%89%E4%BA%8E%E9%9B%B6%22%5D%0A%20%20T%5B%22%E9%95%BF%E5%B0%BE%E6%A0%BC%E5%AD%90%EF%BC%9A%E5%86%B7%E9%97%A8%E4%B8%93%E4%B8%9A%E5%9F%9F%22%5D%20--%3E%7C%22%E7%AC%AC%201%20%E6%9D%A1%22%7C%20V3%5B%22%E8%BE%B9%E7%95%8C%E4%BB%8E%E6%97%A0%E5%88%B0%E6%9C%89%EF%BC%9A%E4%BB%B7%E5%80%BC%E6%9C%80%E5%A4%A7%22%5D%0A%20%20V2%20--%3E%20Q%5B%22%E9%85%8D%E9%A2%9D%E4%BB%8E%E5%A4%B4%E9%83%A8%E6%8C%AA%E5%90%91%E9%95%BF%E5%B0%BE%22%5D%0A%20%20V3%20--%3E%20Q%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<p><span class="marginnote">给一个数：若「写邮件」这类头部意图占真实日志的 90%，一万条里就有九千条在重复敲同一扇门；而某个冷门格子可能一万条里一条都没有。按频率配额等于把预算全花在最不缺数据的地方——所以配额按格子的信息价值分，不按出现频率分。</span></p><p><span class="marginnote">InstructGPT 的提示池明写两源——API 真实提交（主体）与标注员撰写（补多样性）；「模型生成」不在其中，是 Self-Instruct 之后的合成路线才有的做法。三条分布各补一块：真实形状、格子保障、廉价密度。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多样性有上界：离目标行为太远的提示稀释预算，也制造假覆盖——格子填了，问题却没人会问。分类法本身要随政策与产品迭代，是活文档，版本走第一课的数据卡。日志的隐私约束是硬边界，有些格子只能靠自写与合成去补。最后，覆盖无法被证明，只能被审计：矩阵是账本不是证书，欠覆盖格子迟早要还，晚还不如实记录。对抗性的提示分布不在本课——刻意制造失败的那一支，是下一课红队数据的题。</p><p><span class="marginnote">「假覆盖」指格子账面上填了，填进去的却是没人真会问的问题——像健身房会员名单上有人，不代表他真的来练。审计覆盖时不只要看格子空不空，还要抽看格子里的提示像不像真实用户会说的话。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>提示分布定义偏好的管辖范围；缺席处没有边界，只有外推。</li><li>三条来源各补一块：日志给真实形状，自写给格子保障，合成给密度与变体。</li><li>先立意图分类法（按行为边界切），再按四维覆盖矩阵配额与验收。</li><li>长尾过采的机制是边际信息量：头部重复样本趋近零价值。</li><li>覆盖只能审计不能证明；持有集从薄弱格子切，让验证诚实。</li><li>出处：Ouyang 等 InstructGPT，2022；Zhou 等 LIMA，2023；多样性度量见合成数据课。</li></ul>',7))])}const _=o(C,[["render",p]]);export{F as __pageData,_ as default};
